(() => {
  'use strict';
  if (document.body.dataset.page !== 'embeds') return;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
  const base=String((window.AURALIS_CONFIG||{}).apiBase||'').replace(/\/$/,'');
  const api=async(path,options={})=>{const r=await fetch(`${base}${path}`,{credentials:'include',...options,headers:{Accept:'application/json','Content-Type':'application/json',...(options.headers||{})}});const ct=r.headers.get('content-type')||'';const raw=await r.text();let d=raw;if(ct.includes('json')){try{d=JSON.parse(raw)}catch{d={error:'Invalid JSON response from the backend.'}}}if(!r.ok)throw new Error(d?.error||d||`Request failed (${r.status})`);return d;};
  const $=s=>document.querySelector(s),guild=()=>new URLSearchParams(location.search).get('guild')||localStorage.getItem('auralis:selected-guild')||'';
  const toast=t=>{const n=document.createElement('div');n.className='toast';n.textContent=t;document.body.append(n);setTimeout(()=>n.remove(),2500);};
  const blank=()=>({id:'',name:'New embed',enabled:true,title:'',description:'',color:'#7c6cf5',url:'',authorName:'',authorIconUrl:'',thumbnailUrl:'',imageUrl:'',footerText:'',footerIconUrl:'',timestamp:false,content:'',fields:[]});
  let presets=[],selectedId='',channels=[];
  function setEditor(p){const x=structuredClone(p||blank());selectedId=p?.id||'';for(const [sel,val] of Object.entries({'[data-embed-id]':x.id,'[data-embed-name]':x.name,'[data-embed-title]':x.title,'[data-embed-color]':x.color,'[data-embed-description]':x.description,'[data-embed-url]':x.url,'[data-embed-content]':x.content,'[data-embed-author]':x.authorName,'[data-embed-author-icon]':x.authorIconUrl,'[data-embed-thumbnail]':x.thumbnailUrl,'[data-embed-image]':x.imageUrl,'[data-embed-footer]':x.footerText,'[data-embed-footer-icon]':x.footerIconUrl,'[data-embed-timestamp]':Boolean(x.timestamp),'[data-embed-enabled]':x.enabled!==false,'[data-embed-fields]':(x.fields||[]).map(f=>`${f.name} | ${f.value} | ${f.inline?'true':'false'}`).join('\n')})){const el=$(sel);if(!el)continue;if(el.type==='checkbox')el.checked=val;else el.value=val??'';} $('[data-embed-id]').readOnly=Boolean(selectedId);$('[data-embed-editor-title]').textContent=selectedId?`Edit ${x.name||x.id}`:'Create an embed';$('[data-embed-state]').textContent=selectedId?'Saved preset':'Draft';$('[data-embed-delete]').disabled=!selectedId;$('[data-embed-send]').disabled=!selectedId;renderPreview();renderList();}
  function collect(){const fields=$('[data-embed-fields]').value.split(/\r?\n/).map(line=>{const [name,value,inline]=line.split('|').map(v=>v.trim());return {name,value,inline:/^(true|yes|1|inline)$/i.test(inline||'')}}).filter(f=>f.name&&f.value).slice(0,25);return {id:$('[data-embed-id]').value.trim().toLowerCase(),name:$('[data-embed-name]').value.trim(),title:$('[data-embed-title]').value,description:$('[data-embed-description]').value,color:$('[data-embed-color]').value,url:$('[data-embed-url]').value,content:$('[data-embed-content]').value,authorName:$('[data-embed-author]').value,authorIconUrl:$('[data-embed-author-icon]').value,thumbnailUrl:$('[data-embed-thumbnail]').value,imageUrl:$('[data-embed-image]').value,footerText:$('[data-embed-footer]').value,footerIconUrl:$('[data-embed-footer-icon]').value,timestamp:$('[data-embed-timestamp]').checked,enabled:$('[data-embed-enabled]').checked,fields};}
  function renderPreview(){const p=collect();$('[data-preview-author]').textContent=p.authorName||'Auralis';const ai=$('[data-preview-author-icon]');ai.innerHTML=p.authorIconUrl?`<img src="${esc(p.authorIconUrl)}" alt="">`:'';$('[data-preview-title]').textContent=p.title||'Embed title';$('[data-preview-description]').textContent=p.description||'Your description preview appears here.';$('[data-preview-fields]').innerHTML=p.fields.map(f=>`<div class="custom-embed-preview-field ${f.inline?'inline':''}"><strong>${esc(f.name)}</strong><span>${esc(f.value)}</span></div>`).join('');const image=$('[data-preview-image]');if(p.imageUrl){image.src=p.imageUrl;image.hidden=false;}else{image.removeAttribute('src');image.hidden=true;}$('[data-preview-footer]').textContent=p.footerText||'Auralis';$('[data-preview-timestamp]').textContent=p.timestamp?new Date().toLocaleString() : '';}
  function renderList(){const q=($('[data-embed-search')?.value||'').toLowerCase();const root=$('[data-embed-list]');if(!root)return;const arr=presets.filter(p=>`${p.name} ${p.title} ${p.id}`.toLowerCase().includes(q));$('[data-embed-count]').textContent=presets.length;root.innerHTML=arr.length?arr.map(p=>`<button type="button" class="panel-list-item ${p.id===selectedId?'active':''}" data-embed-select="${esc(p.id)}"><div><strong>${esc(p.name)}</strong><span>${esc(p.title||'No title')} · ${p.fields?.length||0} fields</span></div><span>${p.enabled===false?'Paused':'Ready'}</span></button>`).join(''):'<div class="empty-state">No saved embeds yet.</div>';root.querySelectorAll('[data-embed-select]').forEach(b=>b.onclick=()=>setEditor(presets.find(p=>p.id===b.dataset.embedSelect)));}
  async function load(){const id=guild();if(!id)return;try{const [data,res]=await Promise.all([api(`/api/guilds/${id}/embed-presets`),api(`/api/guilds/${id}/resources`)]);presets=data.presets||[];channels=(res.channels||[]).filter(c=>[0,5,15,16].includes(Number(c.type)));const select=$('[data-embed-send-channel]');const previous=select.value;select.innerHTML='<option value="">Choose a channel…</option>'+channels.map(c=>`<option value="${esc(c.id)}">#${esc(c.name)}</option>`).join('');select.value=previous;setEditor(presets.find(p=>p.id===selectedId)||presets[0]||null);}catch(e){$('[data-embed-list]').innerHTML=`<div class="error-card">${esc(e.message)}</div>`;toast(e.message);}}
  async function save(){const b=collect();if(!b.name)return toast('Name your embed preset.');if(!b.id)b.id=b.name.toLowerCase().replace(/[^a-z0-9_-]/g,'-').slice(0,40);if(!b.title&&!b.description&&!b.fields.length&&!b.imageUrl&&!b.thumbnailUrl)return toast('Add some embed content before saving.');const btn=$('[data-embed-save]');btn.disabled=true;try{const out=selectedId?await api(`/api/guilds/${guild()}/embed-presets/${encodeURIComponent(selectedId)}`,{method:'PATCH',body:JSON.stringify(b)}):await api(`/api/guilds/${guild()}/embed-presets`,{method:'POST',body:JSON.stringify(b)});presets=out.presets||presets;setEditor(out.preset);toast('Embed preset saved.');}catch(e){toast(e.message);$('[data-embed-result]').textContent=e.message;}finally{btn.disabled=false;}}
  async function remove(){if(!selectedId||(window.AuralisConfirmDestructive?!(await window.AuralisConfirmDestructive(`Delete embed preset “${selectedId}”?`,{title:'Delete embed preset?',confirmLabel:'Delete preset'})):!confirm(`Delete embed preset “${selectedId}”?`)))return;try{const out=await api(`/api/guilds/${guild()}/embed-presets/${encodeURIComponent(selectedId)}`,{method:'DELETE'});presets=out.presets||[];setEditor(presets[0]||null);if(!presets.length)setEditor(blank());toast('Embed preset deleted.');}catch(e){toast(e.message);}}
  async function send(){if(!selectedId)return;const channelId=$('[data-embed-send-channel]').value;if(!channelId)return toast('Choose a channel.');const btn=$('[data-embed-send]');btn.disabled=true;try{const out=await api(`/api/guilds/${guild()}/embed-presets/${encodeURIComponent(selectedId)}/send`,{method:'POST',body:JSON.stringify({channelId})});$('[data-embed-result]').innerHTML=`Sent successfully: <a href="${esc(out.url)}" target="_blank" rel="noreferrer">Open message in Discord ↗</a>`;toast('Embed sent to Discord.');}catch(e){toast(e.message);$('[data-embed-result]').textContent=e.message;}finally{btn.disabled=false;}}
  $('[data-embed-save]').addEventListener('click',save);$('[data-embed-delete]').addEventListener('click',remove);$('[data-embed-send]').addEventListener('click',send);$('[data-embed-refresh]').addEventListener('click',load);$('[data-embed-new]').addEventListener('click',()=>setEditor(blank()));$('[data-embed-reset]').addEventListener('click',()=>setEditor(presets.find(p=>p.id===selectedId)||blank()));document.querySelectorAll('[data-embed-title],[data-embed-description],[data-embed-color],[data-embed-author],[data-embed-author-icon],[data-embed-thumbnail],[data-embed-image],[data-embed-footer],[data-embed-footer-icon],[data-embed-timestamp],[data-embed-fields]').forEach(el=>el.addEventListener('input',renderPreview));
  window.addEventListener('auralis:guild-ready',load);if(document.readyState==='complete')setTimeout(load,700);else window.addEventListener('load',()=>setTimeout(load,300));
})();
